export abstract class SpeechTreeNodePort { abstract list(): Promise<SpeechTreeNode[]>; }
@Injectable()
export class SpeechTreeNodeMockAdapter extends SpeechTreeNodePort { async list(): Promise<SpeechTreeNode[]> { return speechTreeNodes; } }
@Injectable({ providedIn: 'root' })
export class SpeechTreeNodeFacade {
  private readonly port = inject(SpeechTreeNodePort);
  readonly items = signal<SpeechTreeNode[]>([]);
  readonly loading = signal(false);
  constructor() { void this.load(); }
  async load(): Promise<void> { this.loading.set(true); this.items.set(await this.port.list()); this.loading.set(false); }

  // Amendment 4 (2026-08-31) — TRAINING phase (ADR-016) and Dual Authorization (ADR-018).
  // Use cases simulated in the prototype (no real call to the Claude/Anthropic API nor
  // indexing/TTS pipeline — see TODO[architect] in ADRs 015/016/017).
  // NIV note: English-only product; pt-BR locale removed (see ADR-018-english-only-product).

  /** A node/locale is only "active" (available in CONV's pure-retrieval runtime, see
   * ADR-015) when both confirmations (caregiver + patient) are done for that locale. */
  isActive(no: SpeechTreeNode, locale: Locale): boolean {
    const c = no.content[locale];
    return c.caregiverConfirmed && c.patientConfirmed;
  }

  /** Creates a new proposal coming from the TRAINING conversation with the LLM (ADR-016) —
   * born as a draft, with no confirmation, no cached audio. */
  propose(patientId: string, parentId: string | null, textEn: string): string {
    const id = `no-training-${Date.now()}`;
    this.items.update(list => [...list, {
      id, patientId, parentId, type: 'phrase', order: list.length + 1, engineFeatureRef: null, proposedByTraining: true,
      content: {
        en: { text: textEn, audioRef: null, caregiverConfirmed: false, patientConfirmed: false },
      },
    }]);
    return id;
  }

  /** Caregiver confirmation (Screen 08, DASH shell) — RBAC training.node.approve.caregiver. */
  confirmCaregiver(id: string, locale: Locale): void {
    this.items.update(list => list.map(n =>
      n.id === id ? { ...n, content: { ...n.content, [locale]: { ...n.content[locale], caregiverConfirmed: true } } } : n,
    ));
  }

  /** Patient confirmation (Screen 09, patient-shell) — RBAC training.node.approve.patient.
   * Asynchronous relative to the caregiver's confirmation (no screen handoff, see ADR-016).
   * On completing Dual Authorization, triggers (simulated) ES indexing + ElevenLabs synthesis
   * — in the prototype, it only fills audioRef with an illustrative path. */
  confirmPatient(id: string, locale: Locale): void {
    this.items.update(list => list.map(n => {
      if (n.id !== id) return n;
      const contentLocale = { ...n.content[locale], patientConfirmed: true };
      if (contentLocale.caregiverConfirmed) {
        contentLocale.audioRef = `audio/${locale}/${contentLocale.text.toLowerCase().replace(/[^a-z0-9]+/g, '-')}.mp3`;
      }
      return { ...n, content: { ...n.content, [locale]: contentLocale } };
    }));
  }

  /** Rejects the proposal for this locale — the node stays as a draft. */
  recusar(id: string, locale: Locale): void {
    this.items.update(list => list.map(n =>
      n.id === id ? { ...n, content: { ...n.content, [locale]: { text: n.content[locale].text, audioRef: null, caregiverConfirmed: false, patientConfirmed: false } } } : n,
    ));
  }
  // TODO[fe-autopilot]: real use cases (filters, commands, pagination) over the port
}

export abstract class PatientSessionPort { abstract list(): Promise<PatientSession[]>; }
@Injectable()
export class PatientSessionMockAdapter extends PatientSessionPort { async list(): Promise<PatientSession[]> { return patientSessions; } }
@Injectable({ providedIn: 'root' })
export class PatientSessionFacade {
  private readonly port = inject(PatientSessionPort);
  readonly items = signal<PatientSession[]>([]);
  readonly loading = signal(false);
  constructor() { void this.load(); }
  async load(): Promise<void> { this.loading.set(true); this.items.set(await this.port.list()); this.loading.set(false); }
  /** Provisions a new patient session (ADR-012, Option C — no expiry, revocable).
   * TODO[architect]: real persistence via the "Patient with session" actor in acs-service. */
  provision(patientId: string, deviceId: string, provisionedBy: string): void {
    const id = `sess-${patientId}-${Date.now()}`;
    this.items.update(list => [...list, {
      id, patientId, deviceId, provisionedBy,
      status: 'active', provisionedAt: new Date().toISOString(), revokedAt: null, revokedBy: null,
    }]);
  }
  /** Revokes an active session (constraint SEC-001 — mandatory mechanism, reuses the
   * JWT blacklist already existing in the real project, see rbac/session-policy.md). */
  revoke(id: string, revokedBy: string): void {
    this.items.update(list => list.map(s =>
      s.id === id ? { ...s, status: 'revoked' as const, revokedAt: new Date().toISOString(), revokedBy } : s,
    ));
  }
  // TODO[fe-autopilot]: real use cases (filters, pagination) over the port
}

